//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` for [`RetryError::Transient`] errors, which the
    /// retry policy may retry. Permanent errors are never retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn transient_errors_are_transient() {
        assert!(RetryError::Transient("blip".to_string()).is_transient());
    }

    #[test]
    fn permanent_errors_are_not_transient() {
        assert!(!RetryError::Permanent("bad input".to_string()).is_transient());
    }
}

//! Retry configuration.

/// Configuration for the bounded exponential retry policy.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Upper bound for any retry delay, in milliseconds. Delay growth
    /// saturates at this value instead of overflowing.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Delay, in milliseconds, to wait before the retry at `retry_index`
    /// (0-based; `retry_index == 0` is the delay before the second call).
    ///
    /// The delay is `base_delay_ms * 2^retry_index`, saturating at
    /// `max_delay_ms`. Computed with saturating arithmetic so arbitrarily
    /// large exponents never overflow `u64`.
    pub fn retry_delay_ms(&self, retry_index: u32) -> u64 {
        let base = self.base_delay_ms;
        let max = self.max_delay_ms;
        if base == 0 {
            return 0;
        }
        if base >= max {
            return max;
        }
        // Largest n such that base * 2^n <= max. `doubled` is always
        // <= max < 2^64, so the multiplications never overflow.
        let mut n_ok = 0u32;
        let mut doubled = base;
        while doubled <= max / 2 {
            doubled *= 2;
            n_ok += 1;
        }
        if retry_index <= n_ok {
            // Safe: base << retry_index <= base << n_ok <= max.
            base << retry_index
        } else {
            max
        }
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    fn cfg(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn doubles_until_max_delay() {
        let config = cfg(10, 100, 1000);
        let delays: Vec<u64> = (0..6).map(|i| config.retry_delay_ms(i)).collect();
        assert_eq!(delays, vec![100, 200, 400, 800, 1000, 1000]);
    }

    #[test]
    fn delay_is_zero_when_base_is_zero() {
        let config = cfg(5, 0, 1000);
        assert_eq!(config.retry_delay_ms(0), 0);
        assert_eq!(config.retry_delay_ms(10), 0);
        assert_eq!(config.retry_delay_ms(u32::MAX), 0);
    }

    #[test]
    fn saturates_when_base_is_already_at_cap() {
        let config = cfg(5, 1000, 1000);
        assert_eq!(config.retry_delay_ms(0), 1000);
        assert_eq!(config.retry_delay_ms(100), 1000);
    }

    #[test]
    fn saturates_without_overflow_at_high_exponent() {
        let config = cfg(100, 1, 1000);
        // 2^9 = 512 <= 1000, 2^10 = 1024 > 1000.
        assert_eq!(config.retry_delay_ms(9), 512);
        assert_eq!(config.retry_delay_ms(10), 1000);
        assert_eq!(config.retry_delay_ms(u32::MAX), 1000);
    }

    #[test]
    fn saturates_at_u64_boundary_without_overflow() {
        let max = u64::MAX;
        let config = cfg(100, max / 2 + 1, max);
        // base = 2^63 fits exactly; the next doubling would overflow.
        assert_eq!(config.retry_delay_ms(0), max / 2 + 1);
        assert_eq!(config.retry_delay_ms(1), max);
        assert_eq!(config.retry_delay_ms(u32::MAX), max);
    }

    #[test]
    fn caps_at_max_delay_when_base_is_large() {
        let config = cfg(5, 3, 100);
        // 3*2^5 = 96 <= 100, 3*2^6 = 192 > 100.
        assert_eq!(config.retry_delay_ms(5), 96);
        assert_eq!(config.retry_delay_ms(6), 100);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
///
/// Policy:
/// - `max_attempts` is the total number of calls, including the first.
/// - Only transient errors are retried; permanent errors are returned
///   immediately.
/// - The delay before retry `i` (0-based) is `base_delay_ms * 2^i`,
///   saturating at `max_delay_ms`.
///
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut failures = 0u32;
    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(err) if !err.is_transient() => return Err(err),
            Err(err) => {
                failures += 1;
                if failures >= config.max_attempts {
                    return Err(err);
                }
                sleeper.sleep_ms(config.retry_delay_ms(failures - 1));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    fn transient(msg: &str) -> RetryError {
        RetryError::Transient(msg.to_string())
    }

    fn permanent(msg: &str) -> RetryError {
        RetryError::Permanent(msg.to_string())
    }

    #[test]
    fn succeeds_on_first_call_without_sleeping() {
        let cfg = config(5, 100, 1000);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            Ok(())
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn retries_transient_errors_until_success() {
        let cfg = config(5, 100, 1000);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(transient("blip"))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![100, 200]);
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let cfg = config(1, 100, 1000);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            Err(transient("always"))
        });
        assert_eq!(result, Err(transient("always")));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn exhausts_budget_and_returns_last_transient_error() {
        let cfg = config(3, 10, 1000);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            Err(transient(&format!("fail-{calls}")))
        });
        assert_eq!(result, Err(transient("fail-3")));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_error_returns_immediately() {
        let cfg = config(5, 100, 1000);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            Err(permanent("bad input"))
        });
        assert_eq!(result, Err(permanent("bad input")));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn permanent_error_after_transient_stops_retrying() {
        let cfg = config(5, 100, 1000);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            if calls == 1 {
                Err(transient("blip"))
            } else {
                Err(permanent("missing job"))
            }
        });
        assert_eq!(result, Err(permanent("missing job")));
        assert_eq!(calls, 2);
        assert_eq!(sleeper.sleeps, vec![100]);
    }

    #[test]
    fn delays_grow_exponentially_and_saturate() {
        let cfg = config(10, 100, 1000);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&cfg, &mut sleeper, || Err(transient("blip")));
        assert!(result.is_err());
        assert_eq!(
            sleeper.sleeps,
            vec![100, 200, 400, 800, 1000, 1000, 1000, 1000, 1000]
        );
    }

    #[test]
    fn zero_base_delay_never_waits() {
        let cfg = config(4, 0, 1000);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&cfg, &mut sleeper, || Err(transient("blip")));
        assert!(result.is_err());
        assert_eq!(sleeper.sleeps, vec![0, 0, 0]);
    }
}

# jobrunner

Small job runner with a pluggable retry policy.

## Retry policy

`run_job` applies a configurable bounded exponential retry policy:

- `max_attempts` is the total number of calls, including the first
  attempt.
- Only `RetryError::Transient` errors are retried; `RetryError::Permanent`
  errors return immediately.
- The delay before retry `i` (0-based) is `base_delay_ms * 2^i`,
  saturating at `max_delay_ms`, so delay growth never overflows.

## Example

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 5,
    base_delay_ms: 100,
    max_delay_ms: 1000,
};
let mut sleeper = FakeSleeper::default();
let mut calls = 0;
let result = run_job(&config, &mut sleeper, || {
    calls += 1;
    if calls < 3 {
        Err(RetryError::Transient("network blip".into()))
    } else {
        Ok(())
    }
});
assert_eq!(result, Ok(()));
assert_eq!(sleeper.sleeps, vec![100, 200]);
```

//! Integration coverage for the public retry policy API.
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

fn transient(msg: &str) -> RetryError {
    RetryError::Transient(msg.to_string())
}

fn permanent(msg: &str) -> RetryError {
    RetryError::Permanent(msg.to_string())
}

#[test]
fn succeeds_after_transient_failures() {
    let cfg = config(5, 100, 1000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(transient("blip"))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![100, 200, 400]);
}

#[test]
fn permanent_error_is_not_retried() {
    let cfg = config(5, 100, 1000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        Err(permanent("missing job"))
    });
    assert_eq!(result, Err(permanent("missing job")));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn attempts_are_bounded_and_include_first_call() {
    let cfg = config(3, 25, 1000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        Err(transient("blip"))
    });
    assert_eq!(result, Err(transient("blip")));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![25, 50]);
}

#[test]
fn delays_saturate_at_max_delay_ms() {
    let cfg = config(100, 1, 1000);
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&cfg, &mut sleeper, || Err(transient("blip")));
    assert!(result.is_err());
    // 99 retries: delays 2^0..=2^9 grow to 512, the rest saturate at 1000.
    let mut expected = (0..10).map(|i| 1u64 << i).collect::<Vec<_>>();
    expected.extend(std::iter::repeat_n(1000, 89));
    assert_eq!(sleeper.sleeps, expected);
}
